<script setup lang="ts">
import {computed, onMounted, ref, watch} from 'vue'
import {supportEmail,legalText,faqs,guides} from '../lib/support-content'
import {locale,t,tr} from '../lib/i18n'
import {asset} from '../lib/assets'
import {api} from '../lib/api'
const props=defineProps<{token:string;privacy?:boolean}>()
const emit=defineEmits<{close:[];security:[]}>()
const view=ref<'settings'|'language'|'notifications'|'privacySettings'|'general'|'security'|'feedback'|'help'|'about'|'faq'|'guidelines'|'safety'|'privacy'|'terms'|'system'|'interactions'>('settings')
const confirm=ref(false),notice=ref(''),error=ref(''),busy=ref(false)
type Card={id:string;position:number;visibility:'everyone'|'friends'|'only_me'}
const cards=ref<Card[]>([]),selected=ref<Card>(),choice=ref<Card['visibility']>('everyone')
const globalProfile=ref<{visibility:Card['visibility']}>(),globalSelected=ref(false)
async function saveGlobalVisibility(){if(busy.value)return;busy.value=true;error.value='';try{globalProfile.value=await api('/profiles/me',{method:'PATCH',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':'application/json'},body:JSON.stringify({visibility:choice.value})});globalSelected.value=false;notice.value=t('visibilitySaved')}catch{error.value=t('saveFailed')}finally{busy.value=false}}
onMounted(()=>{if(props.privacy)void openPrivacy()})
const scopes=['everyone','friends','only_me'] as const
const hapticsAvailable=ref(typeof navigator.vibrate==='function')
async function openPrivacy(){view.value='privacySettings';busy.value=true;error.value='';try{globalProfile.value=await api('/profiles/me',{headers:{Authorization:`Bearer ${props.token}`}});cards.value=(await api<{items:Card[]}>('/users/me/image-cards',{headers:{Authorization:`Bearer ${props.token}`}})).items}catch{error.value=t('loadFailed')}finally{busy.value=false}}
async function saveVisibility(){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{const updated=await api<Card>(`/users/me/image-cards/${selected.value.id}`,{method:'PATCH',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':'application/json'},body:JSON.stringify({visibility:choice.value})});cards.value=cards.value.map(c=>c.id===updated.id?updated:c);selected.value=undefined;notice.value=t('visibilitySaved')}catch{error.value=t('saveFailed')}finally{busy.value=false}}
function openPage(page:typeof view.value){notice.value='';error.value='';if(page==='security')emit('security');else if(page==='privacySettings')void openPrivacy();else view.value=page}
function haptic(){if(preferences.value.haptics&&hapticsAvailable.value&&!navigator.vibrate(15))hapticsAvailable.value=false}
const defaults={notifications:true,incoming:true,replies:true,system:true,haptics:true,recommendations:true,systemFont:false}
const preferences=ref({...defaults,...JSON.parse(localStorage.getItem('maugo-settings')||'{}')})
watch(preferences,v=>{localStorage.setItem('maugo-settings',JSON.stringify(v));document.documentElement.classList.toggle('system-font',v.systemFont)},{deep:true,flush:'sync'})
const categories=['incoming','replies','system'] as const
const generalItems=['haptics','recommendations','systemFont'] as const
const pages=[['security','08-interface-icons/icon-lock-lime-22'],['privacySettings','08-interface-icons/icon-shield-lime-22'],['notifications','08-interface-icons/icon-bell-lime-22'],['general','08-interface-icons/icon-settings-light-24'],['language','08-interface-icons/icon-globe-lime-22'],['feedback','08-interface-icons/icon-feedback-lime-22'],['help','08-interface-icons/icon-help-lime-22'],['about','08-interface-icons/icon-info-lime-22']] as const

const supportTitles={help:'Help & support',feedback:'Feedback',about:'About MauGo',faq:'Help centre',guidelines:'Community guidelines',safety:'Safety guide',privacy:'Privacy information',terms:'Terms of Use & EULA',system:'System messages',interactions:'Interactions'}
const supportParent=ref<typeof view.value>('settings')
function supportPage(page:typeof view.value){supportParent.value=view.value;openPage(page)}
const feedbackText=ref(''),feedbackEmail=ref(''),feedbackType=ref('Suggestion'),feedbackPhoto=ref('')
const feedbackKey=`maugo-feedback-${props.token}`
const feedbackHistory=ref<{text:string;email:string;type:string;photo:string;time:number}[]>(JSON.parse(localStorage.getItem(feedbackKey)||'[]'))
function saveFeedback(){error.value='';if(feedbackEmail.value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(feedbackEmail.value.trim())){error.value='Enter a valid email address.';return}const items=[{text:feedbackText.value.trim(),email:feedbackEmail.value.trim(),type:feedbackType.value,photo:feedbackPhoto.value,time:Date.now()},...feedbackHistory.value];try{localStorage.setItem(feedbackKey,JSON.stringify(items))}catch{error.value='Unable to save feedback on this device.';return}feedbackHistory.value=items;feedbackText.value='';feedbackEmail.value='';feedbackPhoto.value='';notice.value='Feedback saved on this device. Not sent to support.'}
function attachFeedback(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>feedbackPhoto.value=reader.result as string;reader.readAsDataURL(file)}
const title=computed(()=>view.value in supportTitles?tr(supportTitles[view.value as keyof typeof supportTitles]):t(view.value as Parameters<typeof t>[0]))
function back(){if(busy.value)return;if(globalSelected.value){globalSelected.value=false;return}if(selected.value){selected.value=undefined;return}if(confirm.value)confirm.value=false;else if(view.value==='settings')emit('close');else{view.value=['faq','guidelines','safety','privacy','terms','system','interactions'].includes(view.value)?supportParent.value:'settings';notice.value='';error.value=''}}
async function cleared(){busy.value=true;error.value='';try{const keys='caches' in window?await caches.keys():[];const temporary=keys.filter(k=>k.startsWith('maugo-temp-'));await Promise.all(temporary.map(k=>caches.delete(k)));confirm.value=false;notice.value=t(temporary.length?'cacheDeleted':'cacheCleared')}catch{error.value=t('cacheFailed')}finally{busy.value=false}}
</script>
<template>
<section class="settings-flow" @click="haptic" @keydown.esc.stop="back">
<header><button id="settings-back" :aria-label="t('back')" @click="back"><img :src="asset('08-interface-icons/icon-chevron-left-light-settings-22')" alt=""></button><h1>{{title}}</h1><span></span></header>
<Transition name="settings-page" mode="out-in"><div :key="view" class="settings-body">
<template v-if="view==='settings'"><div v-for="(group,index) in [pages.slice(0,3),pages.slice(3,5),pages.slice(5)]" :key="index" class="settings-group settings-main"><button v-for="[page,icon] in group" :key="page" :id="`${page}-settings`" class="settings-row" @click="openPage(page)"><img :src="asset(icon)" alt=""><span>{{t(page)}}</span><small v-if="page==='language'">{{locale==='en'?'English':'한국어'}}</small><b aria-hidden="true">›</b></button></div></template>
<template v-else-if="view==='language'"><p>{{t('chooseLanguage')}}</p><div class="language-options"><button v-for="lang in ['en','ko'] as const" :key="lang" :data-language="lang" :aria-pressed="locale===lang" @click="locale=lang"><span>{{lang==='en'?'English':'한국어'}}</span><b>{{locale===lang?'✓':''}}</b></button></div></template>
<template v-else-if="view==='notifications'"><div class="settings-group"><label class="settings-row"><span>{{t('allowNotifications')}}</span><input id="allow-notifications" v-model="preferences.notifications" type="checkbox" role="switch"><i aria-hidden="true"></i></label><label v-for="item in categories" :key="item" class="settings-row" :class="{'category-disabled':!preferences.notifications}"><span>{{t(item)}}</span><input :id="`${item}-notifications`" v-model="preferences[item]" type="checkbox" role="switch" :disabled="!preferences.notifications"><i aria-hidden="true"></i></label></div></template>
<template v-else-if="view==='privacySettings'"><button v-if="globalProfile" id="global-profile-visibility" class="settings-row" :disabled="busy" @click="globalSelected=true;choice=globalProfile.visibility;notice=''"><span>{{tr('Profile visibility')}}</span><small>{{t(globalProfile.visibility)}}</small><b>›</b></button><p>{{t('visibilityScope')}}</p><p v-if="busy" role="status">{{t('loading')}}</p><p v-else-if="!cards.length">{{t('noCards')}}</p><div class="settings-group"><button v-for="card in cards" :key="card.id" :id="card===cards[0]?'profile-visibility':undefined" class="settings-row" :disabled="busy" @click="selected=card;choice=card.visibility;notice='' "><span>{{t('imageCard')}} {{card.position+1}}</span><small>{{t(card.visibility)}}</small><b>›</b></button></div><p v-if="notice" role="status">{{notice}}</p></template>
<template v-else-if="view==='help'">
<p>{{t('helpNote')}}</p>
<section class="support-services"><h2>{{tr('Self service')}}</h2><div class="support-grid"><button id="help-centre" @click="supportPage('faq')"><img :src="asset('08-interface-icons/icon-help-lime-22')" alt=""><span>{{tr('Help centre')}}</span></button><button id="community-guidelines" @click="supportPage('guidelines')"><img :src="asset('08-interface-icons/icon-shield-lime-22')" alt=""><span>{{tr('Guidelines')}}</span></button><button id="safety-guide" @click="supportPage('safety')"><img :src="asset('08-interface-icons/icon-lock-lime-22')" alt=""><span>{{tr('Safety guide')}}</span></button><button id="help-delete" @click="emit('security')"><img :src="asset('08-interface-icons/icon-info-lime-22')" alt=""><span>{{tr('Delete account')}}</span></button></div></section>
<div class="support-message"><img :src="asset('02-bird-static/female-4')" alt=""><div><strong>{{tr('Hello, from MauGo.')}}</strong><p>{{tr('Find quick answers in Help centre, or leave your suggestions in Feedback.')}}</p><p>{{tr('Feedback is saved only on this device. No support service is connected.')}}</p><button v-for="[question] in faqs.slice(0,4)" :key="question" @click="supportPage('faq')">{{tr(question)}}</button></div></div>
<div class="support-bottom"><button id="support-feedback" @click="supportPage('feedback')">{{t('feedback')}}</button><button id="help-privacy" @click="supportPage('privacy')">{{tr('Privacy information')}}</button></div><p>{{tr('Support email')}}: {{supportEmail}} · {{tr('Pending Smith')}}</p>
</template>
<template v-else-if="view==='faq'"><div class="faq-list"><details v-for="[question,answer] in faqs" :key="question"><summary>{{tr(question)}}</summary><p>{{tr(answer)}}</p></details></div></template>
<template v-else-if="view==='feedback'">
<div class="feedback-types"><button v-for="kind in ['Suggestion','Bug','Experience','Other']" :key="kind" :aria-pressed="feedbackType===kind" @click="feedbackType=kind">{{tr(kind)}}</button></div><p>{{tr('Help make this little space better.')}}</p>
<form novalidate @submit.prevent="saveFeedback"><label class="support-field">{{tr('Your feedback')}}<textarea id="feedback-text" v-model="feedbackText" maxlength="1000" :placeholder="tr('What would you like us to improve?')"></textarea></label><label class="support-field">{{tr('Contact email (optional)')}}<input id="feedback-email" v-model="feedbackEmail" type="email" :aria-invalid="!!error"></label><img v-if="feedbackPhoto" class="feedback-photo" :src="feedbackPhoto" alt="Feedback attachment"><button v-if="feedbackPhoto" type="button" class="text-button" @click="feedbackPhoto=''">{{tr('Remove attachment')}}</button><label class="feedback-upload">{{tr('Add a photo')}}<input id="feedback-photo" type="file" accept="image/*" @change="attachFeedback"></label><p>Saved only on this device. A support service is not connected. Not sent to support.</p><button id="save-feedback" class="primary" :disabled="!feedbackText.trim()">{{tr('Save feedback')}}</button></form><p v-if="notice" role="status">{{notice}}</p>
<div id="feedback-history"><article v-for="item in feedbackHistory" :key="item.time" class="feedback-record"><small>{{new Date(item.time).toLocaleDateString()}} · {{tr(item.type)}} · Saved on this device / Not sent</small><p data-user-content>{{item.text}}</p><img v-if="item.photo" class="feedback-photo" :src="item.photo" alt="Saved feedback attachment"></article></div>
</template>
<template v-else-if="view==='about'"><div class="about-logo"><img :src="asset('01-brand-scenes/maugo-wordmark')" alt="MauGo"><p>{{tr('A little bird. A little story.')}}</p><small>Version 0.1.0</small></div><button v-for="page in ['guidelines','terms','privacy','help','system','interactions'] as const" :key="page" :id="`about-${page}`" class="settings-row" @click="supportPage(page)"><span>{{tr(supportTitles[page])}}</span><b>›</b></button><p>Support email: {{supportEmail}} · Pending Smith</p></template>
<template v-else-if="view==='guidelines'||view==='safety'"><article class="support-policy"><section v-for="[heading,copy] in guides[view]" :key="heading"><h2>{{tr(heading)}}</h2><p>{{tr(copy)}}</p></section></article></template>
<template v-else-if="view==='privacy'||view==='terms'"><article class="support-policy"><p>Official text pending Smith (E2). Not ready for release.</p><template v-if="view==='privacy'"><h2>Privacy policy</h2><p>{{legalText.privacy}}</p></template><template v-else><h2>Terms of service</h2><p>{{legalText.terms}}</p><h2>EULA</h2><p>{{legalText.eula}}</p></template></article></template>
<template v-else-if="view==='system'||view==='interactions'"><div class="support-empty"><img :src="asset('01-brand-scenes/envelope')" alt=""><h2>{{tr(view==='system'?'You are all caught up.':'Nothing here yet.')}}</h2><p>No {{view==='system'?'system message':'interaction'}} feed is connected.</p></div></template>
<template v-else><div class="settings-group"><label v-for="item in generalItems" :key="item" class="settings-row"><span>{{t(item)}}</span><input :id="item" :disabled="item==='haptics'&&!hapticsAvailable" :checked="preferences[item]" @change="preferences[item]=($event.target as HTMLInputElement).checked" type="checkbox" role="switch"><i aria-hidden="true"></i></label><button id="clear-cache" class="settings-row" @click="confirm=true;notice=''"><span>{{t('clearCache')}}</span><b aria-hidden="true">›</b></button></div><p>{{t('hapticsNote')}}</p><p id="recommendations-status" role="status">{{t(preferences.recommendations?'recommendationsOn':'recommendationsOff')}}</p><p v-if="!hapticsAvailable">{{t('hapticsUnavailable')}}</p><p>{{t('cacheNote')}}</p><p v-if="notice" role="status">{{notice}}</p></template>
<p v-if="error" role="alert">{{error}}</p></div></Transition>
<Transition name="settings-dialog"><div v-if="selected||globalSelected" class="settings-veil" @click.self="!busy&&(selected=undefined,globalSelected=false)"><section role="dialog" aria-modal="true" :aria-label="globalSelected?tr('Profile visibility'):t('profileVisibility')" class="settings-confirm"><h2>{{globalSelected?tr('Profile visibility'):t('profileVisibility')}}</h2><button v-for="scope in scopes" :key="scope" :data-visibility="scope" :aria-pressed="choice===scope" :disabled="busy" @click="choice=scope">{{t(scope)}} {{choice===scope?'✓':''}}</button><p>{{t('friendsNote')}}</p><p v-if="error" role="alert">{{error}}</p><button id="save-visibility" class="primary" :disabled="busy" @click="globalSelected?saveGlobalVisibility():saveVisibility()">{{t('save')}}</button><button :disabled="busy" @click="selected=undefined;globalSelected=false">{{t('cancel')}}</button></section></div></Transition>
<Transition name="settings-dialog"><div v-if="confirm" class="settings-veil" @click.self="!busy&&(confirm=false)"><section role="dialog" aria-modal="true" :aria-label="t('cacheConfirm')" class="settings-confirm"><h2>{{t('cacheConfirm')}}</h2><p>{{t('cacheNote')}}</p><button id="confirm-clear-cache" class="primary" :disabled="busy" @click="cleared">{{t('clearCache')}}</button><button id="cancel-clear-cache" :disabled="busy" @click="confirm=false">{{t('cancel')}}</button></section></div></Transition>
</section>
</template>
<style scoped>
.settings-flow{position:absolute;inset:0;z-index:35;background:#0d1713;color:#d3e5c9;padding-top:48px;display:flex;flex-direction:column}.settings-flow header{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;flex-shrink:0}.settings-flow header button,.settings-flow header>span{width:32px}.settings-flow header button{padding:5px;background:none;display:grid;place-items:center}.settings-flow header img{width:22px;height:22px}.settings-flow h1{font-size:19px;font-weight:500;margin:0}.settings-body{padding:16px 24px 40px;overflow:auto;flex:1}.settings-group{margin-bottom:24px}.settings-row:disabled{opacity:.5}.settings-main{background:#1c2c22;border-radius:16px;padding:0 16px;margin-bottom:22px}.settings-main .settings-row{min-height:56px;border-bottom:0;font-size:13px}.settings-main .settings-row small{font-size:11px}.settings-confirm [aria-pressed=true]{background:#354532}.settings-confirm button:disabled{opacity:.5}.settings-row{display:flex;align-items:center;gap:14px;min-height:62px;width:100%;padding:16px 0;border-bottom:1px solid #ffffff0b;background:none;text-align:left;color:#d3e5c9;font-size:14px;position:relative}.settings-row>span{flex:1}.settings-row>img{width:22px;height:22px;object-fit:contain}.settings-row small{color:#8dae7e;font-size:12px}.settings-row>b{font-size:22px;font-weight:400;color:#8dae7e}.settings-body p,.settings-confirm p{font-size:12px;line-height:22px;color:#8dae7e;margin:4px 0 24px}.settings-row input{position:absolute;right:0;width:44px;height:26px;opacity:0;cursor:pointer;margin:0;z-index:1}.settings-row i{width:44px;height:26px;border-radius:20px;background:#354532;transition:background .2s;flex-shrink:0}.settings-row i:after{content:'';display:block;width:20px;height:20px;border-radius:50%;background:#a2b797;margin:3px;transition:transform .2s,background .2s}.settings-row input:checked+i{background:#b5fa70}.settings-row input:checked+i:after{transform:translateX(18px);background:#19362b}.settings-row input:focus-visible+i{outline:2px solid #b5fa70;outline-offset:4px}.category-disabled{opacity:.4}.settings-veil{position:absolute;inset:0;background:#030805b8;backdrop-filter:blur(5px);display:flex;align-items:center;padding:24px;z-index:1}.settings-confirm{width:100%;padding:26px 22px 14px;border:1px solid #ffffff12;border-radius:24px;background:#1c2c22;text-align:center}.settings-confirm h2{font-size:20px;font-weight:500;margin:0 0 16px}.settings-confirm button{display:block;width:100%;min-height:48px;border-radius:24px;margin:10px 0;background:none;color:#b5fa70}.settings-confirm .primary{background:#b5fa70;color:#19362b}.settings-page-enter-active,.settings-page-leave-active{transition:opacity .18s,transform .18s}.settings-page-enter-from{opacity:0;transform:translateX(16px)}.settings-page-leave-to{opacity:0;transform:translateX(-12px)}.settings-dialog-enter-active,.settings-dialog-leave-active{transition:opacity .22s}.settings-dialog-enter-active .settings-confirm,.settings-dialog-leave-active .settings-confirm{transition:transform .22s}.settings-dialog-enter-from,.settings-dialog-leave-to{opacity:0}.settings-dialog-enter-from .settings-confirm,.settings-dialog-leave-to .settings-confirm{transform:translateY(20px) scale(.97)}
.support-services h2,.support-policy h2{font-size:16px;font-weight:500}.support-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:22px -8px 32px}.support-grid button{background:none;color:#b5fa70;font-size:26px;padding:0}.support-grid img{width:26px;height:26px;object-fit:contain}.support-grid span{display:block;font-size:10px;margin-top:10px}.support-message{display:flex;gap:12px}.support-message>img{width:38px;height:42px;object-fit:contain}.support-message>div{background:#1c2c22;border-radius:4px 18px 18px;padding:18px;flex:1}.support-message strong{font-size:14px}.support-message p{margin:12px 0}.support-message button{display:block;background:none;color:#b5fa70;text-align:left;text-decoration:underline;font-size:12px;line-height:22px;padding:4px 0}.support-bottom{display:flex;gap:12px;margin:26px 0}.support-bottom button,.feedback-upload{border:1px solid #8dae7e55;border-radius:24px;color:#b5fa70;background:none;padding:12px;font-size:12px;flex:1}.faq-list details{border-bottom:1px solid #ffffff12;padding:20px 0}.faq-list summary{font-size:14px;cursor:pointer}.faq-list p{margin:14px 0 0;animation:answer-in .2s}.feedback-types{display:flex;gap:8px;margin-bottom:20px}.feedback-types button{border-radius:18px;background:#1c2c22;color:#8dae7e;padding:9px 12px;font-size:12px}.feedback-types [aria-pressed=true]{background:#b5fa70;color:#19362b}.support-field{display:block;font-size:13px;margin:20px 0}.support-field textarea,.support-field input{display:block;width:100%;box-sizing:border-box;background:#1c2c22;color:#d3e5c9;border:1px solid #8dae7e33;border-radius:14px;margin-top:10px;padding:14px;font:inherit}.support-field textarea{height:144px;resize:vertical}.feedback-upload{display:block;text-align:center;cursor:pointer;margin:16px 0}.feedback-upload{position:relative}.feedback-upload input{position:absolute;inset:0;width:100%;opacity:0;cursor:pointer}.feedback-upload:focus-within{outline:2px solid #b5fa70;outline-offset:3px}.feedback-photo{width:100%;max-height:200px;object-fit:contain;border-radius:14px}.settings-body form>.primary{width:100%;min-height:48px;border-radius:24px}.feedback-record{border-bottom:1px solid #ffffff12;padding:20px 0;overflow-wrap:anywhere}.feedback-record small{font-size:10px;color:#8dae7e}.feedback-record p{white-space:pre-wrap;margin:12px 0}.about-logo{text-align:center;padding:32px 0}.about-logo img{width:160px}.about-logo p{margin:20px 0 6px}.about-logo small{color:#8dae7e}.support-policy p{overflow-wrap:anywhere}.support-empty{text-align:center;padding-top:100px}.support-empty img{width:88px}.support-empty h2{font-size:16px}@keyframes answer-in{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:translateY(0)}}
</style>
